const clean=(v,n=4000)=>String(v??"").trim().slice(0,n), list=(v,n=20)=>[...new Set((Array.isArray(v)?v:String(v??"").split(",")).map(x=>clean(x,100)).filter(Boolean))].slice(0,n);
const parse=(v,f)=>{try{return JSON.parse(v)}catch{return f}}, now=()=>new Date().toISOString();
const json=(data,status=200,headers={})=>new Response(JSON.stringify(data),{status,headers:{"content-type":"application/json; charset=utf-8",...headers}});
const select=`c.*,o.recruiter_name,o.conversation_notes,o.areas_discussed,o.follow_up_questions,o.recommended_next_steps,o.candidate_questions FROM candidates c LEFT JOIN recruiter_observations o ON o.candidate_id=c.id`;
function candidate(r){return r&&{id:r.id,firstName:r.first_name,lastName:r.last_name,preferredName:r.preferred_name,email:r.email,phone:r.phone,university:r.university,degreeProgram:r.degree_program,major:r.major,graduationDate:r.graduation_date,gpa:r.gpa,workAuthorization:r.work_authorization,desiredFunction:r.desired_function,technicalInterests:parse(r.technical_interests,[]),preferredLocations:parse(r.preferred_locations,[]),relevantCoursework:r.relevant_coursework,relevantSkills:parse(r.relevant_skills,[]),projectExperience:r.project_experience,eventCode:r.event_code,resumeName:r.resume_name,resumeText:r.resume_text,recordStatus:r.record_status,approvalStatus:r.approval_status,approvalTimestamp:r.approval_timestamp,approvedBy:r.approved_by,summary:parse(r.summary_json,null),createdAt:r.created_at,updatedAt:r.updated_at,observations:{recruiterName:r.recruiter_name||"",conversationNotes:r.conversation_notes||"",areasDiscussed:r.areas_discussed||"",followUpQuestions:r.follow_up_questions||"",recommendedNextSteps:r.recommended_next_steps||"",candidateQuestions:r.candidate_questions||""}}}
async function body(req){if(!(req.headers.get("content-type")||"").includes("application/json"))throw Error("Expected JSON.");return req.json()}
async function getOne(env,id){const r=await env.DB.prepare(`SELECT ${select} WHERE c.id=?`).bind(id).first();return r?json({candidate:candidate(r)}):json({error:"Candidate not found."},404)}
async function getList(req,env){const u=new URL(req.url),q=clean(u.searchParams.get("q"),200).toLowerCase(),s=clean(u.searchParams.get("status"),40),e=clean(u.searchParams.get("event"),80);let sql=`SELECT ${select} WHERE 1=1`,b=[];if(s){sql+=" AND c.record_status=?";b.push(s)}if(e){sql+=" AND c.event_code=?";b.push(e.toUpperCase())}if(q){sql+=" AND lower(c.first_name||' '||c.last_name||' '||c.email||' '||c.university||' '||c.major||' '||c.relevant_skills||' '||c.project_experience) LIKE ?";b.push(`%${q}%`)}sql+=" ORDER BY c.updated_at DESC LIMIT 250";const r=await env.DB.prepare(sql).bind(...b).all();return json({candidates:r.results.map(candidate)})}
async function metric(env,session,event,id=null,duration=null){await env.DB.prepare("INSERT INTO measurements(session_id,event_name,candidate_id,duration_ms,created_at) VALUES(?,?,?,?,?)").bind(clean(session,100),clean(event,100),id,duration,now()).run()}
async function create(req,env){const x=await body(req),required=["firstName","lastName","email","university","degreeProgram","major","graduationDate","desiredFunction","eventCode"],missing=required.filter(k=>!clean(x[k]));if(missing.length)return json({error:`Complete required fields: ${missing.join(", ")}.`},400);if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(clean(x.email)))return json({error:"Enter a valid email address."},400);const id=crypto.randomUUID(),t=now();let key=null,name=null,text=clean(x.resumeText,20000)||null;if(x.resume?.base64&&x.resume?.name){const bytes=Uint8Array.from(atob(x.resume.base64),c=>c.charCodeAt(0));if(bytes.byteLength>5e6)return json({error:"Resume must be 5 MB or smaller."},400);name=clean(x.resume.name,160);key=`resumes/${id}/${name.replace(/[^a-zA-Z0-9._-]/g,"_")}`;await env.UPLOADS.put(key,bytes,{httpMetadata:{contentType:clean(x.resume.type,100)||"application/octet-stream"}});if(!text&&/^text\//.test(x.resume.type||""))text=new TextDecoder().decode(bytes).slice(0,20000)}
await env.DB.prepare(`INSERT INTO candidates(id,first_name,last_name,preferred_name,email,phone,university,degree_program,major,graduation_date,gpa,work_authorization,desired_function,technical_interests,preferred_locations,relevant_coursework,relevant_skills,project_experience,event_code,resume_key,resume_name,resume_text,record_status,approval_status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(id,clean(x.firstName,80),clean(x.lastName,80),clean(x.preferredName,80)||null,clean(x.email,200),clean(x.phone,40)||null,clean(x.university,160),clean(x.degreeProgram,160),clean(x.major,160),clean(x.graduationDate,40),clean(x.gpa,20)||null,clean(x.workAuthorization,120)||null,clean(x.desiredFunction,160),JSON.stringify(list(x.technicalInterests)),JSON.stringify(list(x.preferredLocations)),clean(x.relevantCoursework),JSON.stringify(list(x.relevantSkills)),clean(x.projectExperience),clean(x.eventCode,80).toUpperCase(),key,name,text,"New","Pending",t,t).run();await metric(env,x.sessionId||id,"candidate_submitted",id,Number(x.durationMs)||null);return json({id,confirmationCode:id.slice(0,8).toUpperCase()},201)}
async function update(req,env,id){const x=await body(req),exists=await env.DB.prepare("SELECT id FROM candidates WHERE id=?").bind(id).first();if(!exists)return json({error:"Candidate not found."},404);const t=now();if(x.recordStatus){if(!STATUSES.includes(x.recordStatus))return json({error:"Unsupported record status."},400);await env.DB.prepare("UPDATE candidates SET record_status=?,updated_at=? WHERE id=?").bind(x.recordStatus,t,id).run()}if(x.observations){const o=x.observations;await env.DB.prepare(`INSERT INTO recruiter_observations(candidate_id,recruiter_name,conversation_notes,areas_discussed,follow_up_questions,recommended_next_steps,candidate_questions,updated_at) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(candidate_id) DO UPDATE SET recruiter_name=excluded.recruiter_name,conversation_notes=excluded.conversation_notes,areas_discussed=excluded.areas_discussed,follow_up_questions=excluded.follow_up_questions,recommended_next_steps=excluded.recommended_next_steps,candidate_questions=excluded.candidate_questions,updated_at=excluded.updated_at`).bind(id,clean(o.recruiterName,120),clean(o.conversationNotes),clean(o.areasDiscussed),clean(o.followUpQuestions),clean(o.recommendedNextSteps),clean(o.candidateQuestions),t).run();await env.DB.prepare("UPDATE candidates SET updated_at=? WHERE id=?").bind(t,id).run()}return getOne(env,id)}
function context(c){return{"Candidate profile":{university:c.university,degreeProgram:c.degreeProgram,major:c.major,graduationDate:c.graduationDate,gpa:c.gpa,workAuthorization:c.workAuthorization,desiredFunction:c.desiredFunction,technicalInterests:c.technicalInterests,preferredLocations:c.preferredLocations,relevantCoursework:c.relevantCoursework,relevantSkills:c.relevantSkills,projectExperience:c.projectExperience},Resume:c.resumeText||"Not supplied","Recruiter notes":c.observations}}
function validateSummary(s){if(!s||!Array.isArray(s.statements)||!Array.isArray(s.missingInformation))throw Error("Model response did not match the required summary format.");for(const i of s.statements){if(!clean(i.text)||!Array.isArray(i.citations)||!i.citations.length)throw Error("Every statement needs a citation.");if(i.citations.some(c=>!SOURCES.includes(c)))throw Error("Unknown citation.");if(PROTECTED.test(i.text)||DECISION.test(i.text))throw Error("Generated summary contained prohibited content.")}if(PROTECTED.test(JSON.stringify(s))||DECISION.test(JSON.stringify(s)))throw Error("Generated output failed the responsible-use check.");return{statements:s.statements.slice(0,8).map(i=>({text:clean(i.text,500),citations:[...new Set(i.citations)]})),keySkills:list(s.keySkills,12),relevantExperience:list(s.relevantExperience,8),missingInformation:list(s.missingInformation,12),generatedAt:now(),model:clean(s.model,80)||"gpt-4.1-mini"}}
async function model(env,c){if(!env.OPENAI_API_KEY)throw Error("AI generation is unavailable because OPENAI_API_KEY is not configured.");const instructions="Create a factual candidate snapshot from only the supplied JSON. No outside knowledge. Never rank, score, recommend employment action, or infer protected/sensitive characteristics. Flag missing data rather than guessing. Return strict JSON. Every statement needs citations from Candidate profile, Resume, or Recruiter notes.";const schema={type:"object",additionalProperties:false,properties:{statements:{type:"array",items:{type:"object",additionalProperties:false,properties:{text:{type:"string"},citations:{type:"array",items:{type:"string",enum:SOURCES}}},required:["text","citations"]}},keySkills:{type:"array",items:{type:"string"}},relevantExperience:{type:"array",items:{type:"string"}},missingInformation:{type:"array",items:{type:"string"}}},required:["statements","keySkills","relevantExperience","missingInformation"]};const r=await fetch("https://api.openai.com/v1/responses",{method:"POST",headers:{authorization:`Bearer ${env.OPENAI_API_KEY}`,"content-type":"application/json"},body:JSON.stringify({model:env.OPENAI_MODEL||"gpt-4.1-mini",instructions,input:JSON.stringify(context(c)),text:{format:{type:"json_schema",name:"candidate_summary",strict:true,schema}}})});if(!r.ok)throw Error(`AI provider returned ${r.status}.`);const d=await r.json(),out=d.output_text||d.output?.flatMap(x=>x.content||[]).find(x=>x.type==="output_text")?.text;if(!out)throw Error("AI provider returned no summary.");return validateSummary({...JSON.parse(out),model:env.OPENAI_MODEL||"gpt-4.1-mini"})}
async function generate(env,id){const r=await getOne(env,id);if(r.status!==200)return r;try{const s=await model(env,(await r.json()).candidate);await env.DB.prepare("UPDATE candidates SET summary_json=?,approval_status='Pending',approval_timestamp=NULL,approved_by=NULL,updated_at=? WHERE id=?").bind(JSON.stringify(s),now(),id).run();return json({summary:s})}catch(e){return json({error:e.message},503)}}
async function review(req,env,id){const x=await body(req);if(!APPROVALS.includes(x.action))return json({error:"Choose Approved or Rejected."},400);const r=await env.DB.prepare("SELECT summary_json FROM candidates WHERE id=?").bind(id).first();if(!r)return json({error:"Candidate not found."},404);let s=parse(r.summary_json,null);if(!s)return json({error:"Generate a summary first."},400);if(x.editedStatements)s=validateSummary({...s,statements:x.editedStatements,model:s.model});const t=now();await env.DB.prepare("UPDATE candidates SET summary_json=?,approval_status=?,approval_timestamp=?,approved_by=?,updated_at=? WHERE id=?").bind(JSON.stringify(s),x.action,t,clean(x.reviewer,120)||"Recruiter",t,id).run();return getOne(env,id)}
async function csv(env){const r=await env.DB.prepare(`SELECT ${select} ORDER BY c.updated_at DESC`).all(),h=["Candidate ID","Name","Email","University","Degree Program","Major","Graduation Date","Desired Function","Skills","Record Status","Approval Status","Approved By","Updated At"],esc=v=>`"${String(v??"").replaceAll('"','""')}"`,lines=[h.map(esc).join(","),...r.results.map(candidate).map(c=>[c.id,`${c.firstName} ${c.lastName}`,c.email,c.university,c.degreeProgram,c.major,c.graduationDate,c.desiredFunction,c.relevantSkills.join("; "),c.recordStatus,c.approvalStatus,c.approvedBy,c.updatedAt].map(esc).join(","))];return new Response(lines.join("\n"),{headers:{"content-type":"text/csv","content-disposition":"attachment; filename=talentiq-candidates.csv"}})}
function asset(path){const item=STATIC[path]||STATIC["/index.html"];return new Response(item.body,{headers:{"content-type":item.type,"cache-control":path==="/"||path==="/index.html"?"no-cache":"public, max-age=3600"}})}
async function route(req,env){const u=new URL(req.url),p=u.pathname,m=req.method;try{if(p==="/api/health")return json({ok:true,database:"D1",uploads:"R2",aiConfigured:Boolean(env.OPENAI_API_KEY)});if(p==="/api/candidates"&&m==="GET")return getList(req,env);if(p==="/api/candidates"&&m==="POST")return create(req,env);if(p==="/api/export.csv"&&m==="GET")return csv(env);if(p==="/api/measurements"&&m==="POST"){const x=await body(req);await metric(env,x.sessionId,x.eventName,x.candidateId||null,Number(x.durationMs)||null);return json({ok:true},201)}const a=p.match(/^\/api\/candidates\/([^/]+)(?:\/(summary|review))?$/);if(a){if(!a[2]&&m==="GET")return getOne(env,a[1]);if(!a[2]&&m==="PATCH")return update(req,env,a[1]);if(a[2]==="summary"&&m==="POST")return generate(env,a[1]);if(a[2]==="review"&&m==="POST")return review(req,env,a[1])}if(p.startsWith("/api/"))return json({error:"Not found."},404);return asset(p)}catch(e){console.error(e);return json({error:"TalentIQ could not complete that request. Your entered information has not been cleared."},500)}}
